-- 反编译自 dfz64.dll 内嵌字节码 004d841e（unluac 2025-12-23；仅供分析）
-- 程序内副本修正（只改写法，键名与原字节码一致）：长字符串开头多出的换行（1 处，反编译器输出问题）
local function YDF_LoadFunction()
  GetLuaValue([[
            if dmpHook_PetNeidan_Shop_OnEvent == nil then
                dm_g_PetNeidan_Shop_CurWeek = 0
                dm_g_PetNeidan_Shop_ServerObj = 0
                dmpHook_PetNeidan_Shop_OnEvent = PetNeidan_Shop_OnEvent
                function PetNeidan_Shop_OnEvent(event)
                    if event == "NEIDAN_SHOP_UPDATE" and arg0 == "show" then
                        if arg1 and arg2 then
                            dm_g_PetNeidan_Shop_CurWeek = tonumber(arg1)
                            if tonumber(arg2) > 0 then
                                dm_g_PetNeidan_Shop_ServerObj = tonumber(arg2)
                            end
                        end
                    end
                    dmpHook_PetNeidan_Shop_OnEvent(event)
                end
            end
        ]])
  GetLuaValue("        function dmYDF_BuySP(ID, num, curWeek, serverObj)\n            Clear_XSCRIPT()\n            Set_XSCRIPT_Function_Name(\"OnClientBuyItem\")\n            Set_XSCRIPT_ScriptID(505111)\n            Set_XSCRIPT_Parameter(0, ID)\n            Set_XSCRIPT_Parameter(1, num)\n            Set_XSCRIPT_Parameter(2, curWeek)\n            Set_XSCRIPT_Parameter(3, serverObj)\n            Set_XSCRIPT_ParamCount(4)\n            Send_XSCRIPT()\n        end\n        \n        function dmYDF_BuyItem(pageName1, pageName2, name, curWeek, serverObj)\n            local jpCount = LuaFnGetDanqiCount(\"blue\")\n            local zpCount = LuaFnGetDanqiCount(\"purple\")\n            local spCount = LuaFnGetDanqiCount(\"orange\")\n            local jbCount = Player:GetData(\"MONEY\")\n            local ybCount = Player:GetData(\"YUANBAO\")\n        \n            local count = Lua_GetNeiDanShop_ItemsTotalCount(pageName1, pageName2)\n            local items = Lua_GetNeiDanShopData(pageName1, pageName2, 1, count)\n            if type(items) ~= \"table\" then\n                return 0, 8\n            end\n            local item_count = table.getn(items)\n            for i = 1, item_count do\n                if name == DataPool:Lua_GetItemNameByIndex(items[i].itemid) then\n                    local itemId = items[i].itemid\n                    local ID = items[i].ID\n                    local itemNum = items[i].num\n                    local price = items[i].price\n                    local huobi = items[i].huobi\n                    local zhekou = items[i].zhekou -- 折扣\n        \n                    if items[i].leftnum == 0 then\n                        return 0, 3 -- 该商品已售罄，购买失败。 -1不限购\n                    end\n        \n                    if items[i].leftnum == -1 then\n                        return 0, 4 -- 不购买非限购商品\n                    end\n        \n                    local num = Lua_GetNeiDanShop_MaxNumCanBuy(itemId, itemNum)\n                    if num <= 0 then\n                        return 0, 5 -- 计算空间后的最大购买组数（有空间不足的提示）\n                    end\n        \n                    if zhekou > 0 then\n                        price = math.floor(price * zhekou * 0.01)\n                    end\n        \n                    local isBuy = false\n                    if huobi == 1 then\n                        if jpCount >= price then\n                            isBuy = true\n                        end\n                    elseif huobi == 2 then\n                        if zpCount >= price then\n                            isBuy = true\n                        end\n                    elseif huobi == 3 then\n                        if spCount >= price then\n                            isBuy = true\n                        end\n                    elseif huobi == 4 then\n                        if ybCount >= price then\n                            isBuy = true\n                        end\n                    elseif huobi == 5 then\n                        if jbCount >= price then\n                            isBuy = true\n                        end\n                    end\n                    if isBuy then\n                        dmYDF_BuySP(ID, 1, curWeek, serverObj)\n                        return 1, 0\n                    else\n                        return 0, 6\n                    end\n                    break\n                end\n            end\n            return 0, 7\n        end\n        \n        function dmYDF_Buy(aItemName, shopType, aNpcID)\n            local pageName1 = \"\"\n            local pageName2 = \"\"\n            if not dm_g_PetNeidan_Shop_CurWeek or dm_g_PetNeidan_Shop_CurWeek == 0 then\n                return 0, 1\n            end\n            if not dm_g_PetNeidan_Shop_ServerObj or dm_g_PetNeidan_Shop_ServerObj == 0 then\n                return 0, 2\n            end\n        \n            local curWeek = dm_g_PetNeidan_Shop_CurWeek\n            local serverObj = dm_g_PetNeidan_Shop_ServerObj\n            if shopType == 1 then\n                pageName1 = \"灵元锦库\"\n                pageName2 = \"灵元什物\"\n                return dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj)\n            elseif shopType == 2 then\n                pageName1 = \"增益元丹\"\n                pageName2 = \"精品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"珍品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"神品\"\n                return dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj)\n            elseif shopType == 3 then\n                pageName1 = \"护体元丹\"\n                pageName2 = \"精品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"珍品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"神品\"\n                return dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj)\n            elseif shopType == 4 then\n                pageName1 = \"制胜元丹\"\n                pageName2 = \"精品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"珍品\"\n                if dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj) == 1 then\n                    return 1, 0\n                end\n                pageName2 = \"神品\"\n                return dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj)\n            elseif shopType == 5 then\n                pageName1 = \"灵元锦库\"\n                pageName2 = \"灵元锦物\"\n                return dmYDF_BuyItem(pageName1, pageName2, aItemName, curWeek, serverObj)\n            end\n            return 0, -1\n        end\n        \n    ")
end

function YDF_BuyAction(aItemName, aShopType)
  local nRetType, nSubRet = GetLuaValue(fmt("return dmYDF_Buy(\"%s\", %d, %d)", aItemName, aShopType, -1), "nn")
  return nRetType, nSubRet
end

YDF_LoadFunction()
